import { useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

export type AppearanceSettings = {
  theme: string;
  scale: number;
  compact: boolean;
  font: string;
};

const THEMES = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONTS = [
  { value: 'sans', label: 'Гротеск', meta: 'По умолчанию' },
  { value: 'display', label: 'Акцидентный' },
  { value: 'mono', label: 'Моноширинный' },
];

export default function AppearanceSettingsScreen({
  onChange,
}: {
  onChange?: (settings: AppearanceSettings) => void;
}) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    theme: 'system',
    scale: 100,
    compact: false,
    font: 'sans',
  });

  const update = (patch: Partial<AppearanceSettings>) => {
    setSettings((prev) => {
      const next = { ...prev, ...patch };
      onChange?.(next);
      return next;
    });
  };

  const themeLabel =
    THEMES.find((item) => item.value === settings.theme)?.label ?? 'Системная';

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 20,
        maxWidth: 520,
        padding: 24,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        color: 'var(--jx-text)',
      }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 12,
          flexWrap: 'wrap',
        }}
      >
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: 20,
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {themeLabel}
        </JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        <span style={{ fontSize: 13, color: 'var(--jx-text-2)' }}>Тема</span>
        <JxToggle
          items={THEMES}
          value={settings.theme}
          onValueChange={(theme) => update({ theme })}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(scale) => update({ scale })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.compact}
        onChange={(event) => update({ compact: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={FONTS}
        value={settings.font}
        onValueChange={(font) => update({ font })}
      />
    </section>
  );
}

